/**
 * Device presets: the names `--device` and the MCP `device` parameter accept.
 *
 * Three sources, merged in this order (the first to define a key wins):
 *   1. cbrowser's own presets, below - unchanged since they shipped, so
 *      existing renders do not move.
 *   2. Chrome DevTools' device list (device-presets-devtools.ts, generated by
 *      scripts/gen-devtools-devices.ts from a pinned commit) - the newest
 *      maintained list: iPhone 16 family, Pixel 8-10, folds, iPad Pro 13, Surface.
 *   3. Playwright's bundled descriptors, read from the installed playwright.
 *
 * One convention for every entry: the viewport is the device's full screen in
 * CSS pixels, which is what cbrowser's own presets always were. Playwright's
 * `viewport` is the browser's visible area instead (iPhone 15: 393x659 of a
 * 393x852 screen), so its `screen` is used where a descriptor has one.
 *
 * Keys are normalised display names: "iPhone 16 Pro" -> "iphone-16-pro",
 * "Galaxy S9+" -> "galaxy-s9-plus", "iPad (gen 7)" -> "ipad-gen-7". Either form
 * resolves.
 *
 * An unknown name is an error, never a fallback (reported 2026-10-21: an
 * unlisted device rendered 1280x800 desktop and reported success).
 */
import { devices as playwrightDevices } from "playwright";
import type { DeviceDescriptor } from "./types.js";
import { DEVTOOLS_DEVICES } from "./device-presets-devtools.js";
import { normalizeDeviceName } from "./device-names.js";

