export { normalizeDeviceName };

type PlaywrightDescriptor = (typeof playwrightDevices)[string];

function fromPlaywright(name: string, d: PlaywrightDescriptor): DeviceDescriptor {
  // Playwright's exported type leaves out `screen`, but its descriptor data
  // carries it (29 of the 75 portrait devices in 1.58).
  const screen = (d as PlaywrightDescriptor & { screen?: { width: number; height: number } }).screen;
  const size = screen ?? d.viewport;
  return {
    name,
    userAgent: d.userAgent,
    viewport: { width: size.width, height: size.height },
    deviceScaleFactor: d.deviceScaleFactor,
    isMobile: d.isMobile,
    hasTouch: d.hasTouch,
  };
}

function buildPresets(): Record<string, DeviceDescriptor> {
  const presets: Record<string, DeviceDescriptor> = { ...CBROWSER_DEVICES };
  for (const [key, d] of Object.entries(DEVTOOLS_DEVICES)) {
    if (!(key in presets)) presets[key] = d;
  }
  for (const [name, d] of Object.entries(playwrightDevices)) {
    const key = normalizeDeviceName(name);
    if (!(key in presets)) presets[key] = fromPlaywright(name, d);
  }
  return presets;
}

export const DEVICE_PRESETS: Record<string, DeviceDescriptor> = buildPresets();

/** cbrowser's own presets, the default set for `cbrowser parallel devices`. */
export const CBROWSER_DEVICE_KEYS: readonly string[] = Object.keys(CBROWSER_DEVICES);

/** Display names, so "iPad Pro 12.9" finds "ipad-pro-12". The first source to use a name keeps it. */
const KEY_BY_NAME = new Map<string, string>();
for (const [key, d] of Object.entries(DEVICE_PRESETS)) {
  const name = normalizeDeviceName(d.name);
  if (!KEY_BY_NAME.has(name)) KEY_BY_NAME.set(name, key);
}

export type DeviceResolution = { key: string } | { error: string; suggestions: string[] };

/** Resolve a device name to a preset key, or say why not and what is close. */
export function resolveDevice(input: string): DeviceResolution {
  const wanted = normalizeDeviceName(input);
  if (wanted && DEVICE_PRESETS[wanted]) return { key: wanted };
  const byName = wanted ? KEY_BY_NAME.get(wanted) : undefined;
  if (byName) return { key: byName };
  return { error: `Unknown device "${input}"`, suggestions: suggestDevices(wanted) };
}

/** The presets sharing the longest prefix with the name, closest length first. */
function suggestDevices(wanted: string, limit = 8): string[] {
  if (!wanted) return [];
  const sharedPrefix = (key: string): number => {
    let i = 0;
    while (i < key.length && i < wanted.length && key[i] === wanted[i]) i++;
    return i;
  };
  const portrait = Object.keys(DEVICE_PRESETS).filter((k) => !k.endsWith("-landscape"));
  const best = Math.max(...portrait.map(sharedPrefix));
  if (best < 3) return [];
  return portrait
    .filter((k) => sharedPrefix(k) === best)
    .sort((a, b) => Math.abs(a.length - wanted.length) - Math.abs(b.length - wanted.length) || b.localeCompare(a))
    .slice(0, limit);
}

/**
 * What a render actually used: the device preset key (null for no emulation)
 * and the page size. Tools echo this instead of a label: until 2026-10-21
 * empathy_audit answered device "desktop" and visual_cognitive_story described
 * its default as "desktop (1920x1080)" while both rendered at the configured
 * 1280x800 with no emulation (audit M8). An unknown device keeps its name and
 * has no viewport; the browser refuses it at launch.
 *
 * @param fallback the viewport used when no device is set (the configured default)
 */
export function describeRenderTarget(
  device: string | undefined,
  fallback: { width: number; height: number },
): { device: string | null; viewport: { width: number; height: number } | null } {
  if (!device) return { device: null, viewport: { width: fallback.width, height: fallback.height } };
  const resolved = resolveDevice(device);
  if ("error" in resolved) return { device, viewport: null };
  return { device: resolved.key, viewport: { ...DEVICE_PRESETS[resolved.key].viewport } };
}
